# ─── 7. Transformations (discovered by investigate_transforms.py) ──


def bb(cells):
    if not cells:
        return (0, 0, 0, 0)
    r0 = min(c[0] for c in cells)
    r1 = max(c[0] for c in cells)
    c0 = min(c[1] for c in cells)
    c1 = max(c[1] for c in cells)
    return r0, r1, c0, c1


def normalize(cells):
    if not cells:
        return set()
    r0, r1, c0, c1 = bb(cells)
    return {(r - r0, c - c0) for r, c in cells}


def reflect_top(cells):
    r0, r1, c0, c1 = bb(cells)
    return normalize(cells | {(r0 - (r - r0) - 1, c) for r, c in cells})


def reflect_bottom(cells):
    r0, r1, c0, c1 = bb(cells)
    return normalize(cells | {(r1 + (r1 - r) + 1, c) for r, c in cells})


def reflect_left(cells):
    r0, r1, c0, c1 = bb(cells)
    return normalize(cells | {(r, c0 - (c - c0) - 1) for r, c in cells})


def reflect_right(cells):
    r0, r1, c0, c1 = bb(cells)
    return normalize(cells | {(r, c1 + (c1 - c) + 1) for r, c in cells})


def rot90(cells):
    h = bb(cells)[1] - bb(cells)[0] + 1
    return normalize({(c, h - 1 - r) for r, c in cells})


# Helper: add transformed variants of a base pattern
def add_transforms(base_name, base_cells, cat_ships, cat_osc, cat_expl):
    r0, r1, _, _ = bb(base_cells)
    h = r1 - r0 + 1
    xt = {
        "rot90": rot90(base_cells),
        "reflect_top": reflect_top(base_cells),
        "reflect_bottom": reflect_bottom(base_cells),
        "reflect_left": reflect_left(base_cells),
        "reflect_right": reflect_right(base_cells),
    }
    for xform_name, xform_cells in xt.items():
        tag = f"{base_name}_{xform_name}"
        add(tag, xform_cells, cat_ships, f"{xform_name}")


