# ─── 8. Discovered stable patterns (search_stable_12x12.py) ────────


def block_pattern(h, w, mask):
    cells = set()
    for r in range(h):
        for c in range(w):
            if mask >> (r * w + c) & 1:
                cells.add((r, c))
    return cells


