# ─── Demo application ──────────────────────────────────────────────

CELL_SIZE = 12
COLORS = {
    "bg": "#1a1a2e",
    "grid": "#16213e",
    "live": "#e94560",
    "panel": "#0f3460",
    "text": "#eee",
}


class LifeDemo:
    def __init__(self):
        self.root = tk.Tk()
        self.root.title("B356/S2 — Life Demo (30+ ships)")
        self.root.configure(bg=COLORS["panel"])
        self.running = False
        self.gen = 0
        self.speed = 10
        self.cells = set()
        self._saved_cells = set()
        self.ox = self.oy = 0
        self.zoom = 1.0
        self.drag_start = None
        self._pattern_list = []
        self._pattern_index = 0
        self._rotated = False
        self._setup_ui()
        self._bind_keys()
        self._rebuild_pattern_list()
        self._update_info()

    def _rebuild_pattern_list(self):
        cat = self.var_category.get()
        self._pattern_list = CATEGORIES.get(cat, [])
        vals = [n for n, _ in self._pattern_list]
        self.pat_menu["values"] = vals
        if vals:
            self.pat_menu.set(vals[0])
            self._pattern_index = 0
        else:
            self.pat_menu.set("")
        self._load_pattern()

    def _setup_ui(self):
        self.root.geometry("1100x750")

        top = tk.Frame(self.root, bg=COLORS["panel"])
        top.pack(side=tk.TOP, fill=tk.X, padx=6, pady=4)

        # Category selector
        tk.Label(
            top,
            text="Cat:",
            fg=COLORS["text"],
            bg=COLORS["panel"],
            font=("Consolas", 10),
        ).pack(side=tk.LEFT)
        self.var_category = tk.StringVar()
        cats = sorted(CATEGORIES.keys())
        self.cat_menu = ttk.Combobox(
            top, textvariable=self.var_category, values=cats, width=14, state="readonly"
        )
        self.cat_menu.set(cats[0])
        self.cat_menu.pack(side=tk.LEFT, padx=2)
        self.cat_menu.bind(
            "<<ComboboxSelected>>", lambda e: self._rebuild_pattern_list()
        )

        # Pattern selector
        self.var_pattern = tk.StringVar()
        self.pat_menu = ttk.Combobox(
            top, textvariable=self.var_pattern, width=28, state="readonly"
        )
        self.pat_menu.pack(side=tk.LEFT, padx=4)
        self.pat_menu.bind("<<ComboboxSelected>>", lambda e: self._load_pattern())

        # Navigation buttons
        ttk.Button(top, text="<", width=2, command=self._prev_pattern).pack(
            side=tk.LEFT
        )
        ttk.Button(top, text=">", width=2, command=self._next_pattern).pack(
            side=tk.LEFT
        )
        ttk.Button(top, text="Load", command=self._load_pattern).pack(
            side=tk.LEFT, padx=2
        )

        self._rot_var = tk.BooleanVar(value=False)
        tk.Checkbutton(
            top,
            text="90",
            variable=self._rot_var,
            fg=COLORS["text"],
            bg=COLORS["panel"],
            font=("Consolas", 10),
            selectcolor="#333",
            command=self._toggle_rot,
        ).pack(side=tk.LEFT, padx=2)

        self.btn_play = ttk.Button(top, text="Play", command=self._toggle)
        self.btn_play.pack(side=tk.LEFT, padx=4)
        ttk.Button(top, text="Step", command=self._step).pack(side=tk.LEFT, padx=2)
        ttk.Button(top, text="Reset", command=self._reset).pack(side=tk.LEFT, padx=2)
        ttk.Button(top, text="Clear", command=self._clear).pack(side=tk.LEFT, padx=2)

        # Info labels
        self.lbl_info = tk.Label(
            top,
            text="Gen: 0  Pop: 0",
            fg=COLORS["text"],
            bg=COLORS["panel"],
            font=("Consolas", 11),
        )
        self.lbl_info.pack(side=tk.RIGHT, padx=10)
        self.lbl_speed = tk.Label(
            top,
            text="10ms",
            fg=COLORS["text"],
            bg=COLORS["panel"],
            font=("Consolas", 10),
        )
        self.lbl_speed.pack(side=tk.RIGHT, padx=10)
        self.lbl_extra = tk.Label(
            top, text="", fg="#aaa", bg=COLORS["panel"], font=("Consolas", 10)
        )
        self.lbl_extra.pack(side=tk.RIGHT, padx=10)

        # Canvas
        self.canvas = tk.Canvas(self.root, bg=COLORS["bg"], highlightthickness=0)
        self.canvas.pack(fill=tk.BOTH, expand=True)
        self.canvas.bind("<Button-1>", self._on_click)
        self.canvas.bind("<B1-Motion>", self._on_drag)
        self.canvas.bind("<ButtonRelease-1>", self._on_drag_end)
        self.canvas.bind("<MouseWheel>", self._on_scroll)
        self.canvas.bind("<Button-4>", self._on_scroll)
        self.canvas.bind("<Button-5>", self._on_scroll)
        self.canvas.bind("<Configure>", self._on_resize)

        # Bottom help
        help_txt = (
            "Space=Play/Pause  →=Step  R=Reset  C=Clear  "
            "+/-=Speed  Q=Quit  [ ]=Prev/Next  Drag=Pan  Scroll=Zoom"
        )
        tk.Label(
            self.root,
            text=help_txt,
            fg="#888",
            bg=COLORS["panel"],
            font=("Consolas", 9),
        ).pack(side=tk.BOTTOM, fill=tk.X, padx=6, pady=2)

    def _bind_keys(self):
        self.root.bind("<space>", lambda e: self._toggle())
        self.root.bind("<Right>", lambda e: self._step())
        self.root.bind("r", lambda e: self._reset())
        self.root.bind("R", lambda e: self._reset())
        self.root.bind("c", lambda e: self._clear())
        self.root.bind("C", lambda e: self._clear())
        self.root.bind("q", lambda e: self.root.destroy())
        self.root.bind("Q", lambda e: self.root.destroy())
        self.root.bind("+", lambda e: self._speed_up())
        self.root.bind("=", lambda e: self._speed_up())
        self.root.bind("-", lambda e: self._speed_down())
        self.root.bind("[", lambda e: self._prev_pattern())
        self.root.bind("]", lambda e: self._next_pattern())
        self.root.bind("<Prior>", lambda e: self._prev_pattern())  # PageUp
        self.root.bind("<Next>", lambda e: self._next_pattern())  # PageDown

    # ─── Pattern navigation ────────────────────────────────────────

    def _prev_pattern(self):
        if self._pattern_list:
            self._pattern_index = (self._pattern_index - 1) % len(self._pattern_list)
            name = self._pattern_list[self._pattern_index][0]
            self.pat_menu.set(name)
            self._load_pattern()

    def _next_pattern(self):
        if self._pattern_list:
            self._pattern_index = (self._pattern_index + 1) % len(self._pattern_list)
            name = self._pattern_list[self._pattern_index][0]
            self.pat_menu.set(name)
            self._load_pattern()

    # ─── Actions ───────────────────────────────────────────────────

    def _load_pattern(self):
        name = self.var_pattern.get()
        if name in PATTERNS:
            self._saved_cells = {c for c in PATTERNS[name]}
            self.cells = self._apply_rot(self._saved_cells)
            self.gen = 0
            self._update_info()
            self._recenter()
            self._draw()

    def _apply_rot(self, cells):
        if not self._rot_var.get() or not cells:
            return cells
        r0 = min(c[0] for c in cells)
        r1 = max(c[0] for c in cells)
        h = r1 - r0 + 1
        return {(c, h - 1 - r) for r, c in cells}

    def _toggle_rot(self):
        self._rotated = self._rot_var.get()
        if self._saved_cells:
            self.cells = self._apply_rot(self._saved_cells)
            self.gen = 0
            self._update_info()
            self._recenter()
            self._draw()

    def _toggle(self):
        self.running = not self.running
        self.btn_play.config(text="Pause" if self.running else "Play")
        if self.running:
            self._animate()

    def _step(self):
        if self.cells:
            self.cells = step(self.cells)
            self.gen += 1
            self._update_info()
            self._draw()

    def _reset(self):
        self._load_pattern()

    def _clear(self):
        self.cells.clear()
        self.gen = 0
        self._update_info()
        self._draw()

    def _speed_up(self):
        self.speed = max(1, self.speed // 2)
        self.lbl_speed.config(text=f"{self.speed}ms")

    def _speed_down(self):
        self.speed = min(500, self.speed * 2)
        self.lbl_speed.config(text=f"{self.speed}ms")

    def _update_info(self):
        pop = len(self.cells)
        name = self.var_pattern.get()
        # Find extra info
        extra = ""
        for cat, items in CATEGORIES.items():
            for n, info in items:
                if n == name and info:
                    extra = info
                    break
        self.lbl_info.config(text=f"Gen: {self.gen}  Pop: {pop}")
        idx = ""
        if self._pattern_list:
            idx = f" ({self._pattern_index + 1}/{len(self._pattern_list)})"
        self.lbl_extra.config(text=f"{extra}{idx}")

    def _recenter(self):
        if not self.cells:
            self.ox = self.oy = 0
            return
        rs = [c[0] for c in self.cells]
        cs = [c[1] for c in self.cells]
        w = self.canvas.winfo_width() or 800
        h = self.canvas.winfo_height() or 600
        cx = (min(cs) + max(cs)) / 2
        cy = (min(rs) + max(rs)) / 2
        self.ox = w / 2 - cx * CELL_SIZE * self.zoom
        self.oy = h / 2 - cy * CELL_SIZE * self.zoom

    # ─── Drawing ───────────────────────────────────────────────────

    def _draw(self):
        self.canvas.delete("cell")
        if not self.cells:
            self._update_info()
            return
        sz = CELL_SIZE * self.zoom
        w = self.canvas.winfo_width() or 1200
        h = self.canvas.winfo_height() or 800
        for r, c in self.cells:
            x = c * sz + self.ox
            y = r * sz + self.oy
            if -sz < x < w + sz and -sz < y < h + sz:
                self.canvas.create_rectangle(
                    x,
                    y,
                    x + sz - 1,
                    y + sz - 1,
                    fill=COLORS["live"],
                    outline=COLORS["live"],
                    tags="cell",
                )
        self._update_info()

    def _animate(self):
        if not self.running:
            return
        self._step()
        self.root.after(self.speed, self._animate)

    # ─── Mouse handlers ────────────────────────────────────────────

    def _on_click(self, e):
        if not self.cells:
            return
        sz = CELL_SIZE * self.zoom
        c = int((e.x - self.ox) / sz)
        r = int((e.y - self.oy) / sz)
        cell = (r, c)
        if cell in self.cells:
            self.cells.remove(cell)
        else:
            self.cells.add(cell)
        self._draw()

    def _on_drag(self, e):
        if self.drag_start:
            dx = e.x - self.drag_start[0]
            dy = e.y - self.drag_start[1]
            self.ox += dx
            self.oy += dy
            self.drag_start = (e.x, e.y)
            self._draw()

    def _on_drag_end(self, e):
        self.drag_start = None

    def _on_resize(self, e):
        self._draw()

    def _on_scroll(self, e):
        mx, my = e.x, e.y
        old_sz = CELL_SIZE * self.zoom
        factor = 1.15 if e.delta > 0 or e.num == 4 else 0.85
        self.zoom = max(0.2, min(5.0, self.zoom * factor))
        new_sz = CELL_SIZE * self.zoom
        self.ox = mx - (mx - self.ox) * (new_sz / old_sz)
        self.oy = my - (my - self.oy) * (new_sz / old_sz)
        self._draw()

    def run(self):
        self._load_pattern()
        self.root.mainloop()


if __name__ == "__main__":
    LifeDemo().run()
